SELECT 
FROM t_communication_record cr
LEFT JOIN t_user u ON cr.owner_id = u.id
WHERE 1 = 1

    AND cr.owner_id = #{query.dataScopeUserId}


    AND cr.owner_id = #{query.ownerId}


    AND cr.follow_task_id = #{query.followTaskId}


    AND cr.related_object_type = #{query.relatedObjectType}


    AND cr.related_object_id = #{query.relatedObjectId}


    AND cr.status = #{query.status}


    AND (cr.summary LIKE CONCAT('%', #{query.keyword}, '%')
        OR cr.customer_feedback LIKE CONCAT('%', #{query.keyword}, '%')
        OR cr.next_action LIKE CONCAT('%', #{query.keyword}, '%'))

ORDER BY cr.communication_time DESC, cr.id DESC

mapper.insert:
