    next_follow_time, status, version, create_time, create_by, update_time, update_by
) VALUES (
    #{followTaskId}, #{parentRecordId}, #{relatedObjectType}, #{relatedObjectId}, #{ownerId},
    #{communicationMethod}, #{communicationTime}, #{summary}, #{customerFeedback}, #{nextAction},
    #{nextFollowTime}, #{status}, #{version}, #{createTime}, #{createBy}, #{updateTime}, #{updateBy}
)
